CREATE OR REPLACE FUNCTION app.current_tenant()
RETURNS bigint
LANGUAGE sql
STABLE
AS $$
SELECT coalesce(current_setting('app.tenant', true), '0')::bigint
$$;

CREATE OR REPLACE FUNCTION app.tenant_count()
RETURNS bigint
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = app, pg_temp
AS $$
SELECT count(*) FROM pg_catalog.pg_namespace
$$;

CREATE OR REPLACE VIEW app.my_documents WITH (security_barrier = true, security_invoker = true) AS
SELECT id, title FROM app.documents WHERE tenant_id = app.current_tenant();

GRANT SELECT ON app.my_documents TO PUBLIC;
